# WARNING: Under review - generated by LLM.

from .tiny_llm_base import (
    build_state_card,
    memory_session,
)


def test_task_1_state_card_derives_only_public_ledger_state(tmp_path):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="fix the parser")
    session.append("tool_call", tool="read_file", arguments={"path": "a.py"})

    card = build_state_card(session, goal="fix the parser")

    assert card.goal == "fix the parser"
    assert "read_file" in card.current_action
    assert card.phase == "running"


def test_task_1_state_card_tracks_tool_evidence(tmp_path):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="fix the parser")
    call = session.append("tool_call", tool="read_file", arguments={"path": "a.py"})
    session.append(
        "tool_result",
        tool_call_id=call.id,
        tool="read_file",
        is_error=False,
        content="line 1: def parse()",
    )

    card = build_state_card(session, goal="fix the parser")

    assert "line 1: def parse()" in card.last_evidence
    assert card.next_safe_step == "continue the loop"


def test_task_1_state_card_finished_phase_is_terminal(tmp_path):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="fix the parser")
    session.append("run_finished", completed=True, reason="completed", final="done")

    card = build_state_card(session, goal="fix the parser")

    assert card.phase == "finished"
    assert card.current_action == "none"
    assert card.next_safe_step == "none"


def test_task_1_state_card_never_exposes_hidden_reasoning(tmp_path):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="fix the parser")
    session.append("assistant_message", content="I will now reason internally")

    card = build_state_card(session, goal="fix the parser")

    assert "internally" not in card.render()
    assert card.current_action == "generating"


def test_task_2_steering_handle_queues_durably(tmp_path):
    from .tiny_llm_base import SteeringHandle

    session = memory_session(tmp_path, "test-model")
    handle = SteeringHandle(session)
    event = handle.submit("focus on the parser")

    assert event.type == "steering_queued"
    assert session.pending_steering()[0].id == event.id
    delivered = session.deliver_pending_steering()
    assert delivered[0].data["content"] == "focus on the parser"
    assert session.pending_steering() == ()


def test_task_3_cancellation_is_first_writer_wins():
    import pytest

    from .tiny_llm_base import AgentInterrupted, CancellationToken

    cancellation = CancellationToken()

    assert cancellation.cancel("operator interrupt") is True
    assert cancellation.cancel("later timeout") is False
    assert cancellation.cancelled is True
    assert cancellation.reason == "operator interrupt"

    with pytest.raises(AgentInterrupted) as caught:
        cancellation.raise_if_cancelled("model")

    assert caught.value.reason == "operator interrupt"
    assert caught.value.phase == "model"
